package Dialogos;
import model.*; import Dao.*; import services.*;
import javax.swing.*; import javax.swing.table.*; import java.awt.*; import java.math.*; import java.util.*; import java.util.regex.*;

public final class DialogoAltaMasivaProductos extends JDialog {
 private final java.util.List<FacturaPdf.Linea> filas;
 private final java.util.List<TipoIva> ivas=new TipoIvaDao().listarActivos();
 private final DefaultTableModel m=new DefaultTableModel(new String[]{"Crear","Código","Nombre","Compra","Stock","Factor","Costo base","IVA","Venta sugerida"},0){public Class<?> getColumnClass(int c){return c==0?Boolean.class:Object.class;} public boolean isCellEditable(int r,int c){return c==0||c==2||c==4||c==5||c==7||c==8;}};
 private final JTable t=new JTable(m); private final JTextField recargo=new JTextField("40",5); private final JLabel estado=new JLabel(" "); private boolean actualizando; private boolean guardado;
 private static final Color NAVY=new Color(19,48,99), GREEN=new Color(15,125,82);
 public DialogoAltaMasivaProductos(Window owner,FacturaPdf factura,Proveedor proveedor){
 super(owner,"Serena Soft | Alta masiva V5.1",ModalityType.APPLICATION_MODAL);
 filas=factura.lineas.stream().filter(l->l.producto==null).toList();
 JPanel root=new JPanel(new BorderLayout(8,8));root.setBorder(BorderFactory.createEmptyBorder(12,12,12,12));root.setBackground(new Color(238,243,249));setContentPane(root);
 JPanel top=new JPanel(new BorderLayout(5,8)); JLabel titulo=new JLabel("SERENA SOFT | ALTA MASIVA DE PRODUCTOS");titulo.setOpaque(true);titulo.setBackground(NAVY);titulo.setForeground(Color.WHITE);titulo.setFont(new Font("SansSerif",Font.BOLD,20));titulo.setBorder(BorderFactory.createEmptyBorder(14,12,14,12));top.add(titulo,BorderLayout.NORTH);
 JPanel tools=new JPanel(new FlowLayout(FlowLayout.LEFT));tools.add(new JLabel("Recargo sobre costo (%)"));tools.add(recargo);JButton calcular=boton("Calcular precios",NAVY);tools.add(calcular);JButton todos=boton("Seleccionar todos",NAVY), ninguno=boton("Quitar selección",NAVY);tools.add(todos);tools.add(ninguno);top.add(tools);top.add(new JLabel("Revisá unidad, factor e IVA. Precios sobre costo base de factura; confirmar tratamiento fiscal. Alta inactiva, sin stock."),BorderLayout.SOUTH);root.add(top,BorderLayout.NORTH);
 for(var l:filas){String u=l.unidad==null?"":l.unidad.toUpperCase(Locale.ROOT);String stock=u.equals("KG")?"KG":"UN";BigDecimal factor=sugerir(l);TipoIva iva=l.alicuota==null||l.alicuota.signum()==0?null:ivas.stream().filter(v->v.getPorcentaje().compareTo(l.alicuota)==0).findFirst().orElse(null);m.addRow(new Object[]{true,l.codigo,l.descripcion,u,stock,factor==null?"":factor.toPlainString(),"",iva,""});}
 t.setRowHeight(30);t.setAutoResizeMode(JTable.AUTO_RESIZE_OFF);t.getTableHeader().setDefaultRenderer(new DefaultTableCellRenderer(){public Component getTableCellRendererComponent(JTable a,Object v,boolean s,boolean f,int r,int c){super.getTableCellRendererComponent(a,v,s,f,r,c);setBackground(NAVY);setForeground(Color.WHITE);setHorizontalAlignment(CENTER);return this;}});int[] widths={55,125,300,75,65,75,105,100,120};for(int i=0;i<widths.length;i++)t.getColumnModel().getColumn(i).setPreferredWidth(widths[i]);t.getColumnModel().getColumn(4).setCellEditor(new DefaultCellEditor(new JComboBox<>(new String[]{"UN","KG"})));t.getColumnModel().getColumn(7).setCellEditor(new DefaultCellEditor(new JComboBox<>(ivas.toArray(new TipoIva[0]))));root.add(new JScrollPane(t));
 JPanel bottom=new JPanel(new BorderLayout());bottom.add(estado);JPanel buttons=new JPanel(new FlowLayout(FlowLayout.RIGHT));JButton cancelar=boton("Cancelar",Color.GRAY), guardar=boton("Registrar seleccionados",GREEN);buttons.add(cancelar);buttons.add(guardar);bottom.add(buttons,BorderLayout.EAST);root.add(bottom,BorderLayout.SOUTH);
 calcular.addActionListener(e->{if(finEdicion())try{recalcular(true);}catch(Exception ex){error(ex);}});todos.addActionListener(e->{if(finEdicion())for(int i=0;i<m.getRowCount();i++)m.setValueAt(true,i,0);});ninguno.addActionListener(e->{if(finEdicion())for(int i=0;i<m.getRowCount();i++)m.setValueAt(false,i,0);});cancelar.addActionListener(e->dispose());
 m.addTableModelListener(e->{if(!actualizando&&(e.getColumn()==4||e.getColumn()==5))try{m.setValueAt("",e.getFirstRow(),8);recalcular(false);}catch(Exception ex){estado.setText(ex.getMessage());}});
 guardar.addActionListener(e->{if(!finEdicion())return;try{var altas=new ArrayList<AltaMasivaPdfService.Alta>();for(int i=0;i<filas.size();i++)if(Boolean.TRUE.equals(m.getValueAt(i,0))){try{String u=m.getValueAt(i,4).toString();BigDecimal f=num(m.getValueAt(i,5)),p=num(m.getValueAt(i,8));if(!(m.getValueAt(i,7) instanceof TipoIva iva))throw new IllegalArgumentException("Seleccione IVA");if(f.signum()<=0||p.signum()<=0)throw new IllegalArgumentException("Factor y precio deben ser positivos");altas.add(new AltaMasivaPdfService.Alta(filas.get(i),m.getValueAt(i,2).toString().trim(),u,f,p,iva.getIdIva()));}catch(Exception ex){t.changeSelection(i,5,false,false);throw new IllegalArgumentException("Fila "+(i+1)+": "+ex.getMessage());}}if(altas.isEmpty())throw new IllegalArgumentException("Seleccione artículos");if(JOptionPane.showConfirmDialog(this,"Registrar "+altas.size()+" productos inactivos, sin stock. ¿Confirmar datos comerciales?","Confirmar",JOptionPane.YES_NO_OPTION)!=JOptionPane.YES_OPTION)return;new AltaMasivaPdfService().crear(factura,proveedor,altas);guardado=true;JOptionPane.showMessageDialog(this,altas.size()+" productos registrados. Revise y active desde Productos.");dispose();}catch(Exception ex){error(ex);}});
 recalcular(true);Rectangle a=GraphicsEnvironment.getLocalGraphicsEnvironment().getMaximumWindowBounds();setSize(Math.min(1190,a.width-30),Math.min(650,a.height-30));setLocationRelativeTo(owner);setDefaultCloseOperation(DISPOSE_ON_CLOSE);
 }
 public boolean isGuardado(){return guardado;}
 private boolean finEdicion(){return !t.isEditing()||t.getCellEditor().stopCellEditing();}
 private static JButton boton(String s,Color c){JButton b=new JButton(s);b.setBackground(c);b.setForeground(Color.WHITE);b.setFocusPainted(false);b.setFont(new Font("SansSerif",Font.BOLD,12));return b;}
 private void error(Exception e){JOptionPane.showMessageDialog(this,e.getMessage(),"Revisar datos",JOptionPane.WARNING_MESSAGE);}
 private static BigDecimal num(Object v){try{return new BigDecimal(v.toString().trim().replace(',','.'));}catch(Exception e){throw new IllegalArgumentException("Complete el valor numérico");}}
 static BigDecimal sugerir(FacturaPdf.Linea l){String u=l.unidad==null?"":l.unidad.toUpperCase(Locale.ROOT);if(u.equals("UN")||u.equals("KG"))return BigDecimal.ONE;Matcher a=Pattern.compile("(?i)\\b(?:PACK|CAJA|BULTO|DISPLAY)\\s*x\\s*(\\d+)(?![\\d.,])\\s*(?=\\)|$|un\\b|unidades\\b)").matcher(l.descripcion==null?"":l.descripcion);if(a.find())return new BigDecimal(a.group(1));return null;}
 private void recalcular(boolean precios){BigDecimal r=num(recargo.getText());if(r.signum()<0)throw new IllegalArgumentException("Recargo negativo");actualizando=true;try{for(int i=0;i<filas.size();i++){var l=filas.get(i);try{BigDecimal f=num(m.getValueAt(i,5));BigDecimal c=l.importe.divide(l.cantidad.multiply(f),2,RoundingMode.HALF_UP);m.setValueAt(c.toPlainString(),i,6);if(precios||m.getValueAt(i,8).toString().isBlank())m.setValueAt(c.multiply(BigDecimal.ONE.add(r.movePointLeft(2))).setScale(2,RoundingMode.HALF_UP).toPlainString(),i,8);}catch(Exception ex){m.setValueAt("",i,6);if(precios)m.setValueAt("",i,8);}}estado.setText("Revisá las celdas vacías y los precios antes de registrar.");}finally{actualizando=false;}}
}
